input.old_string:
// ---------------------------------------------------------------------------
// Authz helpers
// ---------------------------------------------------------------------------

function assertBoardOrgAccessCtx(ctx: import("../http/types.js").RequestCtx) {
  if (!ctx.actor || ctx.actor.type !== "board") {
    throw forbidden("Board access required");
  }
}

function assertInstanceAdminCtx(ctx: import("../http/types.js").RequestCtx) {
  if (!ctx.actor || ctx.actor.type !== "board") {
    throw forbidden("Instance admin access required");
  }
  // The richer isInstanceAdmin flag lives on the Express req.actor but is not
  // available in the minimal ActorContext. The expressHandler bridge runs the
  // full Express middleware chain first (including auth) so instance-admin
  // checks that depend on req.actor.isInstanceAdmin are enforced at the
  // Express layer via assertInstanceAdmin(req). Here we just ensure
  // board-level authentication as a baseline.
}
